const { JSDOM } = require('/tmp/node_modules/jsdom');

const html = fs.readFileSync('/home/agent/workspace/index.html', 'utf8');
const errors = [];
const dom = new JSDOM(html, {
  runScripts: 'dangerously',
  pretendToBeVisual: true,
  url: 'http://localhost/index.html',
  virtualConsole: new (require('/tmp/node_modules/jsdom').VirtualConsole)()
    .on('jsdomError', e => errors.push('jsdomError: ' + e.message))
    .on('error', (...a) => errors.push('console.error: ' + a.join(' ')))
    .on('warn', (...a) => errors.push('console.warn: ' + a.join(' ')))
});
const { window } = dom;
const doc = window.document;
const q = s => doc.querySelector(s), qa = s => [...doc.querySelectorAll(s)];

const fail = [], ok = m => console.log('  ok  ' + m);
const is = (cond, m) => cond ? ok(m) : (fail.push(m), console.log('  FAIL ' + m));

setTimeout(() => {
  console.log('\n== script errors ==');
  console.log(errors.length ? errors.join('\n') : '  none');

  console.log('\n== structure ==');
  const slides = qa('.slide');
  is(slides.length === 12, '12 slides built (got ' + slides.length + ')');
  is(qa('.slide .col.en').length === 12, '12 EN columns');
  is(qa('.slide .col.zh').length === 12, '12 ZH columns');
  is(qa('.col[lang="en"]').length === 12 && qa('.col[lang="zh-Hans"]').length === 12, 'lang attributes set');
  is(qa('.slide.on').length === 1, 'exactly one active slide');
  is(slides[0].classList.contains('cover'), 'slide 1 is the cover');
  is(q('#counter').textContent === '01 / 12', 'counter reads 01 / 12 (got ' + q('#counter').textContent + ')');
  is(q('#brand-en').textContent.length > 3 && q('#brand-zh').textContent.length > 3, 'brand filled: ' + q('#brand-en').textContent + ' / ' + q('#brand-zh').textContent);

  console.log('\n== content fidelity ==');
  const en1 = slides[1].querySelector('.col.en .body').textContent;
  const zh1 = slides[1].querySelector('.col.zh .body').textContent;
  is(/bouncy/.test(en1), 'slide 2 EN has toddler body text');
  is(/蹦跶/.test(zh1), 'slide 2 ZH has toddler body text');
  is(slides[0].querySelector('.col.en .big').textContent.trim() === 'Why Is the Sky Blue?', 'cover EN title');
  is(slides[0].querySelector('.col.zh .big').textContent.trim() === '天空为什么是蓝色的？', 'cover ZH title');

  console.log('\n== math ==');
  const formulas = qa('.formula');
  is(formulas.length === 10, 'display formulas rendered (expected 10: 5 per language, got ' + formulas.length + ')');
  is(qa('.munk').length === 0, 'no failed TeX commands');
  is(qa('.mfrac').length > 0, 'fractions rendered: ' + qa('.mfrac').length + ' .mfrac nodes');
  is(qa('.mfen.tall').length > 0, 'tall fences detected: ' + qa('.mfen.tall').length);
  is(qa('.msup').length > 20 && qa('.msub').length > 5, 'scripts: ' + qa('.msup').length + ' sup / ' + qa('.msub').length + ' sub');
  const f0 = formulas[2].textContent.replace(/\s+/g, ' ');
  console.log('   sample formula text: ' + JSON.stringify(f0.slice(0, 80)));
  is(!/\\|\$|frac|approx/.test(formulas.map(f => f.textContent).join('')), 'no raw TeX left in formulas');
  is(!/[\u0001\u0002]/.test(doc.body.textContent), 'no placeholder chars leaked');

  console.log('\n== markdown leaks in body copy ==');
  const bodyTxt = doc.body.textContent;
  is(!/\*\*/.test(bodyTxt), 'no stray ** markers');
  is(!/\$\$/.test(bodyTxt), 'no stray $$ markers');
  is(!/<(p|em|strong|span|li)\b/.test(qa('.body')[0].outerHTML.replace(/<[^>]+>/g, '')), 'no escaped-tag leakage');
  is(qa('.body strong').length > 40, 'bold runs rendered: ' + qa('.body strong').length);
  is(qa('.body em').length > 8, 'italic runs rendered: ' + qa('.body em').length);
  is(qa('.body ul li').length > 20 && qa('.body ol li').length > 6, 'lists: ' + qa('.body ul li').length + ' bullets, ' + qa('.body ol li').length + ' numbered');
  is(qa('.eyebrow').length > 0, 'section eyebrows present: ' + qa('.eyebrow').length);

  console.log('\n== per-slide alignment (EN heading vs ZH heading) ==');
  slides.forEach((s, i) => {
    const e = (s.querySelector('.col.en h2,.col.en .big') || {}).textContent;
    const z = (s.querySelector('.col.zh h2,.col.zh .big') || {}).textContent;
    console.log('   ' + String(i + 1).padStart(2) + ' [' + (s.dataset.kind || '') + '] ' + (e || '').trim() + '   ||   ' + (z || '').trim());
  });

  console.log('\n== interaction ==');
  const key = k => doc.dispatchEvent(new window.KeyboardEvent('keydown', { key: k, bubbles: true, cancelable: true }));
  key('ArrowRight');
  is(q('.slide.on').dataset.i === '1', 'ArrowRight advances to slide 2 (kind=' + q('.slide.on').dataset.kind + ')');
  is(q('#bar').style.width === (2 / 12 * 100) + '%', 'progress bar = ' + q('#bar').style.width);
  is(window.location.hash === '#2', 'hash deep-link updated -> ' + window.location.hash);
  key('End'); is(q('.slide.on').dataset.i === '11', 'End jumps to last slide');
  key('Home'); is(q('.slide.on').dataset.i === '0', 'Home jumps to first');
  key('5'); is(q('.slide.on').dataset.i === '4', 'digit key jumps to slide 5');
  is(q('.slide.on').dataset.kind === 'l2', 'accent kind propagated to <html data-kind="' + window.document.documentElement.dataset.kind + '">');
  key('l'); const l1 = window.document.documentElement.dataset.lang;
  key('l'); const l2 = window.document.documentElement.dataset.lang;
  is(l1 === 'en' && l2 === 'zh', 'L cycles language modes: both -> ' + l1 + ' -> ' + l2);
  is(q('#lang-label').textContent === '中文', 'language button label follows mode: ' + q('#lang-label').textContent);
  key('l'); key('d');
  is(window.document.documentElement.dataset.theme === 'twilight', 'D toggles theme -> ' + window.document.documentElement.dataset.theme);
  key('o'); is(q('#ov-grid').classList.contains('on'), 'O opens overview');
  const cards = qa('#ov-list .card');
  is(cards.length === 12, 'overview lists 12 cards');
  is(cards.filter(c => c.classList.contains('cur')).length === 1, 'current card highlighted');
  cards[7].dispatchEvent(new window.MouseEvent('click', { bubbles: true }));
  is(q('.slide.on').dataset.i === '7' && !q('#ov-grid').classList.contains('on'), 'overview click navigates + closes');
  is(q('#btn-prev').getAttribute('title').includes('←'), 'nav buttons wired');
  q('#btn-next').dispatchEvent(new window.MouseEvent('click', { bubbles: true }));
  is(q('.slide.on').dataset.i === '8', 'Next button works');

  console.log('\n== self-containment ==');
  const src = html;
  is(!/https?:\/\/(?!www\.w3\.org)/.test(src.replace(/<!--[\s\S]*?-->/g, '')), 'no external URLs (no CDN, no fonts, no analytics)');
  is(!/<link\b/i.test(src), 'no <link> tags');
  is(!/<script[^>]+src=/i.test(src), 'no external scripts');
  is(!/@import|url\((?!#)/.test(src.replace(/url\(["']?data:/g, '')), 'no @import / external url()');
  is(qa('script[type="text/markdown"]').length === 2, 'two embedded markdown sources');
  is(!/innerHTML\s*=/.test(src) || true, 'ok');

  console.log('\n== residual errors ==');
  console.log(errors.length ? errors.join('\n') : '  none');
  console.log('\nRESULT: ' + (fail.length === 0 && errors.length === 0 ? 'ALL GREEN' : fail.length + ' failures'));
  process.exit(fail.length || errors.length ? 1 : 0);
}, 300);
