{"content": "#!/usr/bin/env python3
"""Merge sky.md (EN) + sky2.md (ZH) -> sky_bilingual.md, grouped by explanation level,
English first then Chinese. Verifies losslessly; refuses to write (and hence to allow any
deletion) unless every content line of both sources survives in the right place."""
import re, sys, hashlib

EN_F, ZH_F, OUT_F = ('/home/agent/workspace/sky.md', '/home/agent/workspace/sky2.md',
                     '/home/agent/workspace/sky_bilingual.md')
en_raw, zh_raw = open(EN_F, encoding='utf-8').read(), open(ZH_F, encoding='utf-8').read()

def parse(raw):
    """-> {'title':str,'lead':[line],'levels':[{'heading':str,'lines':[line]}]}  ('---' dropped)"""
    title, lead, levels, cur = None, [], [], None
    for ln in raw.split('\n'):
        if re.match(r'^---\s*$', ln): continue
        m = re.match(r'^(#{1,6})\s+(.*)$', ln)
        if m and len(m.group(1)) == 1 and cur is None and not any(l.strip() for l in lead):
            title = m.group(2).strip(); continue
        if m and len(m.group(1)) == 2:
            cur = {'heading': m.group(2).strip(), 'lines': []}; levels.append(cur); continue
        (cur['lines'] if cur else lead).append(ln)
    return {'title': title, 'lead': lead, 'levels': levels}

en, zh = parse(en_raw), parse(zh_raw)

# ---------------- pre-flight: the two docs must be structurally identical ----------------
bad = []
if len(en['levels']) != len(zh['levels']): bad.append('level count %d vs %d' % (len(en['levels']), len(zh['levels'])))
if any(not d['title'] for d in (en, zh)): bad.append('missing H1')
for i, (a, b) in enumerate(zip(en['levels'], zh['levels'])):
    sa = [l for l in a['lines'] if l.startswith('### ')]
    sb = [l for l in b['lines'] if l.startswith('### ')]
    if len(sa) != len(sb): bad.append('level %d sub-headings %r vs %r' % (i + 1, sa, sb))
    if any(l.startswith('#####') for l in a['lines'] + b['lines']): bad.append('level %d deeper than ####' % (i + 1))
if bad:
    print('REFUSING TO MERGE:\n  ' + '\n  '.join(bad)); sys.exit(2)

def tidy(ls):
    ls = list(ls)
    while ls and not ls[0].strip(): ls.pop(0)
    while ls and not ls[-1].strip(): ls.pop()
    return ls
def demote(ls):        # ### x -> #### x, so that '### English' / '### 中文' are the backbone
    return [('####' + l[3:]) if l.startswith('### ') else l for l in ls]

# ---------------- build ----------------
P = ['# %s · %s' % (en['title'], zh['title']), '']
P += tidy(en['lead']) + tidy(zh['lead']) + ['']
P += ['> **Bilingual edition · 双语版.** Each level presents the English section first, with the '
      'Simplified Chinese translation directly beneath it. 每个层级先呈现英文原文，随后紧接简体中文译文。', '']
P += ['**Contents · 目录**', '']
for a, b in zip(en['levels'], zh['levels']):
    P += ['1. **%s** · %s' % (a['heading'], b['heading'])]
P += ['', '---']
for a, b in zip(en['levels'], zh['levels']):
    P += ['', '## %s · %s' % (a['heading'], b['heading']), '', '### English', '']
    P += tidy(demote(a['lines'])) + ['', '### 中文（简体）', '']
    P += tidy(demote(b['lines'])) + ['', '---']
out = re.sub(r'\n{3,}', '\n\n', '\n'.join(P).rstrip() + '\n')

# ---------------- verification ----------------
strip_hash = lambda s: re.sub(r'^#+\s*', '', s).rstrip()
def src_lines(d):
    """all content lines of a source doc, per level, headings flattened, blanks/HRs gone"""
    return {i: [strip_hash(l) for l in lv['lines'] if l.strip()] for i, lv in enumerate(d['levels'])}
def merged_lines(text):
    """for each level chunk, the English block and the Chinese block, same normalisation"""
    body = text.split('\n---', 1)[1] if '\n---' in text else text
    chunks = [c for c in re.split(r'^## ', body, flags=re.M)[1:]]
    res = {'EN': {}, 'ZH': {}}
    for i, c in enumerate(chunks):
        c = re.sub(r'\n---\s*$', '', c).rstrip()
        head, rest = c.split('\n', 1)
        if '### English' not in rest or '### 中文（简体）' not in rest:
            raise AssertionError('level %d missing an English or Chinese block' % (i + 1))
        _, enb, zhb = re.split(r'^### English\s*$|^### 中文（简体）\s*$', rest, flags=re.M)
        res['EN'][i] = [strip_hash(l) for l in enb.strip('\n').split('\n') if l.strip()]
        res['ZH'][i] = [strip_hash(l) for l in zhb.strip('\n').split('\n') if l.strip()]
    return res, chunks

fails = []
mres, chunks = merged_lines(out)
want_en, want_zh = src_lines(en), src_lines(zh)
if len(chunks) != 3: fails.append('merged file has %d level chunks, expected 3' % len(chunks))
for i in range(len(chunks)):
    for label, want, lang in (('EN', want_en, 'EN'), ('ZH', want_zh, 'ZH')):
        w, g = want.get(i, []), mres[lang].get(i, [])
        if w != g:
            fails.append('level %d %s: %d source lines vs %d merged' % (i + 1, label, len(w), len(g)))
            import difflib
            fails += ['      ' + d[:140] for d in list(difflib.unified_diff(w, g, lineterm=''))[:14]]
# headings must be recoverable from the combined form
for i, c in enumerate(chunks):
    head = c.split('\n', 1)[0]
    if head != '%s · %s' % (en['levels'][i]['heading'], zh['levels'][i]['heading']):
        fails.append('level %d combined heading unexpected: %r' % (i + 1, head))
# title + lead lines must be present verbatim
if not out.startswith('# %s · %s' % (en['title'], zh['title'])): fails.append('combined H1 wrong')
for d, lang in ((en, 'EN'), (zh, 'ZH')):
    for l in tidy(d['lead']):
        if l.strip() not in out: fails.append('%s lead line lost: %r' % (lang, l[:60]))
# every '### ' in the merged file must be an English/Chinese marker only
stray = [l for l in out.split('\n') if l.startswith('### ') and l.strip() not in ('### English', '### 中文（简体）')]
if stray: fails.append('stray ### headings: %r' % stray[:3])

if fails:
    print('REFUSING TO WRITE — verification failed:\n  ' + '\n  '.join(fails)); sys.exit(3)

open(OUT_F, 'w', encoding='utf-8').write(out)
n_en = sum(len(v) for v in want_en.values()); n_zh = sum(len(v) for v in want_zh.values())
print('verified: every content line of both sources reproduced in place')
print('  EN %d content lines + 3 headings | ZH %d content lines + 3 headings' % (n_en, n_zh))
print('  wrote %s (%d bytes)' % (OUT_F, len(out.encode())))
print('  sha256 sky.md=%s  sky2.md=%s  merged=%s' % (
      hashlib.sha256(en_raw.encode()).hexdigest()[:10],
      hashlib.sha256(zh_raw.encode()).hexdigest()[:10],
      hashlib.sha256(out.encode()).hexdigest()[:10]))
", "path": "/tmp/merge.py"}

