:root{
  --ar:"Noto Sans Arabic","Noto Kufi Arabic","Tajawal","Cairo","Geeza Pro","Al Bayan","Baghdad",
       "Damascus","SF Arabic","Segoe UI","Tahoma","Arial",sans-serif;
