  --dur:.45s; --ease:cubic-bezier(.22,.72,.28,1); --r:16px; --fs:1;
  /* ألوان الطبقات — ثابتة في السمتين لأنها تمثيل علمي */
  --c-crust:#d8b365; --c-litho:#b9975a; --c-mantle:#8e9f5d; --c-tz:#7d8f52;
  --c-outer:#dd7a3c; --c-inner:#f6cf4b;
}
