  --bg:#120e0b; --bg2:#1d1410; --ink:#f4ece2; --ink2:#c9b8a5; --ink3:#96806a;
  --panel:#1b1410; --panel2:#241a13; --rule:#3a2a1f; --rule2:#4d382a;
