*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0; background:var(--bg); color:var(--ink);
  font-family:var(--ar); font-size:calc(1rem * var(--fs)); line-height:1.95;   /* سطر واسع: الكهفيّات الطويلة تحتاج مساحة */
