button{font-family:inherit;font-size:inherit;color:inherit}
:focus-visible{outline:3px solid var(--accent);outline-offset:3px;border-radius:8px}

/* ---- أرقام وألفاظ لاتينية: تُعزل اتجاهياً حتى لا تختلط داخل نصٍّ من اليمين لليسار ---- */
.num{direction:ltr;unicode-bidi:isolate;display:inline-block;font-variant-numeric:tabular-nums lining-nums}
.lat{direction:ltr;unicode-bidi:isolate;display:inline-block}
.lat:lang(en),.lat{font-family:var(--lat);font-style:normal}
.skip{position:absolute;left:-9999px}
.skip:focus{inset-inline-start:8px;top:8px;z-index:50;background:var(--panel);padding:8px 14px;border-radius:10px;border:1px solid var(--accent)}

/* ================== الهيكل ================== */
header,footer{display:flex;align-items:center;gap:14px;padding:10px clamp(12px,2.6vw,28px);
  background:var(--panel2);border-bottom:1px solid var(--rule);flex:0 0 auto;z-index:8;flex-wrap:wrap}
footer{border-bottom:0;border-top:1px solid var(--rule);gap:10px}
.brand{flex:1 1 auto;min-width:0;display:flex;align-items:baseline;gap:10px}
.brand b{font-size:clamp(15px,1.5vw,19px);font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.brand span{color:var(--ink3);font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tools{display:flex;gap:6px;flex-wrap:wrap}
.btn{appearance:none;border:1px solid var(--rule2);background:var(--btn);padding:7px 13px;border-radius:999px;
  cursor:pointer;font-weight:700;font-size:13px;line-height:1;display:inline-flex;gap:7px;align-items:center;
  transition:background .18s,border-color .18s,transform .12s}
.btn:hover{background:var(--btnh);border-color:var(--accent)}
.btn:active{transform:translateY(1px)}
.btn .k{opacity:.55;font-weight:500;font-size:11px}
.track{flex:1 1 auto;height:5px;border-radius:999px;background:var(--rule);overflow:hidden;position:relative;min-width:50px}
.track i{position:absolute;inset-block:0;inset-inline-start:0;width:0;background:linear-gradient(to left,#8fa15c,#d8b365 35%,#dd7a3c 70%,#f6cf4b);
  border-radius:999px;transition:width var(--dur) var(--ease)}
.counter{font-size:12.5px;color:var(--ink2);font-variant-numeric:tabular-nums}
.gauge{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--ink2);white-space:nowrap}
.gauge b{color:var(--accent);font-weight:800;font-variant-numeric:tabular-nums}
.gauge .dial{width:56px;height:8px;border-radius:999px;background:var(--rule);overflow:hidden}
.gauge .dial i{display:block;height:100%;width:0;border-radius:999px;background:linear-gradient(to left,#8fa15c,#f6cf4b);transition:width var(--dur) var(--ease)}
.hint{font-size:11.5px;color:var(--ink3)}
@media (max-width:820px){.hint{display:none}}
kbd{font-family:var(--ar);font-size:11px;font-weight:700;background:var(--panel);border:1px solid var(--rule2);
  border-bottom-width:2px;border-radius:6px;padding:2px 7px;display:inline-block}

/* ================== الشرائح ================== */
main{flex:1 1 auto;position:relative;z-index:1;min-height:0}
.slide{position:absolute;inset:clamp(10px,1.5vw,20px);display:none;
  grid-template-columns:minmax(0,1.06fr) minmax(0,.94fr);gap:clamp(14px,2.2vw,30px);
  background:var(--panel);border:1px solid var(--rule);border-radius:var(--r);box-shadow:var(--shadow);
  padding:clamp(16px,2.4vw,34px);overflow:auto}
.slide.on{display:grid;animation:pop var(--dur) var(--ease) both}
@keyframes pop{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
.slide.solo{grid-template-columns:minmax(0,1fr)}
@media (max-width:900px){.slide{grid-template-columns:minmax(0,1fr);grid-auto-rows:min-content}}
.colstart{display:flex;flex-direction:column;min-width:0}
.eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:11.5px;font-weight:800;color:var(--accent);margin-bottom:10px}
.eyebrow::before{content:"";inline-size:22px;block-size:2px;background:var(--accent);border-radius:2px}
h1,h2{font-weight:800;line-height:1.35;margin:0 0 .45em;letter-spacing:0}
h1{font-size:clamp(30px,4.6vw,58px)}
h2{font-size:clamp(22px,2.7vw,36px)}
h3{font-size:clamp(16px,1.5vw,20px);font-weight:800;margin:1.1em 0 .35em;line-height:1.5}
p{margin:0 0 .85em}
.lead{font-size:clamp(15.5px,1.35vw,20px);color:var(--ink2);line-height:1.95}
ul{margin:0 0 1em;padding-inline-start:1.15em;list-style:none}
li{position:relative;margin:.5em 0;padding-inline-start:.2em}
ul>li::before{content:"";position:absolute;inset-inline-start:-.95em;top:.78em;inline-size:7px;block-size:7px;
  border-radius:50%;background:var(--accent);opacity:.8}
strong,b{font-weight:800;color:var(--accent)}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}
.chip{font-size:12.5px;font-weight:700;padding:6px 12px;border-radius:999px;background:var(--panel2);
  border:1px solid var(--rule);color:var(--ink2);display:inline-flex;gap:6px;align-items:center}
.chip s{width:8px;height:8px;border-radius:50%;background:var(--c);text-decoration:none;display:inline-block}
.note{background:var(--panel2);border-inline-start:4px solid var(--accent);border-radius:0 12px 12px 0;
  padding:12px 16px;margin:14px 0;font-size:14.5px;color:var(--ink2)}
.note b{color:var(--ink)}
.fig{background:var(--panel2);border:1px solid var(--rule);border-radius:14px;padding:clamp(10px,1.4vw,18px);
  display:flex;flex-direction:column;gap:8px;min-width:0}
.fig figcaption{font-size:12.5px;color:var(--ink3);line-height:1.7}
.fig svg{width:100%;height:auto;display:block}
table{border-collapse:collapse;width:100%;font-size:14px;font-variant-numeric:tabular-nums}
th,td{text-align:start;padding:8px 9px;border-bottom:1px solid var(--rule)}
th{font-size:11.5px;font-weight:800;color:var(--ink3);white-space:nowrap}
td b{font-size:15px}
tbody tr:hover{background:var(--panel2)}
.swatch{display:inline-block;width:11px;height:11px;border-radius:3px;background:var(--c);margin-inline-end:6px;vertical-align:-1px}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,200px),1fr));gap:12px;margin:6px 0 14px}
.card{background:var(--panel2);border:1px solid var(--rule);border-radius:13px;padding:13px 15px;
  border-top:4px solid var(--c,var(--accent))}
.card h4{margin:0 0 6px;font-size:15.5px;font-weight:800}
.card .big{font-size:clamp(24px,2.6vw,34px);font-weight:800;line-height:1.25;font-variant-numeric:tabular-nums;color:var(--ink)}
.card small{display:block;color:var(--ink3);font-size:12.5px;line-height:1.7;margin-top:4px}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,140px),1fr));gap:10px;margin:12px 0}
.stat{background:var(--panel2);border:1px solid var(--rule);border-radius:12px;padding:11px 13px}
.stat b{display:block;font-size:clamp(22px,2.4vw,32px);font-weight:800;line-height:1.2;color:var(--accent);font-variant-numeric:tabular-nums}
.stat span{font-size:12.5px;color:var(--ink3);line-height:1.6;display:block;margin-top:2px}
.two{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:14px}
.tl{list-style:none;padding:0;margin:6px 0}
.tl li{padding-inline-start:0;margin:0 0 14px;display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:start}
.tl .dot{inline-size:34px;block-size:34px;border-radius:50%;background:var(--c,var(--accent));color:#241a10;
  display:flex;align-items:center;justify-content:center;font-weight:800;font-size:13px;flex:0 0 auto;
  font-variant-numeric:tabular-nums;direction:ltr}
.tl b{display:block}
.tl small{color:var(--ink3);font-size:12.5px;line-height:1.7;display:block}
.gloss{columns:2;column-gap:26px;font-size:14px}
@media (max-width:760px){.gloss{columns:1}}
.gloss div{break-inside:avoid;margin-bottom:9px}
.gloss b{color:var(--ink)}
.gloss i{font-style:normal;color:var(--ink3)}

/* ================== الطبقات فوق المحتوى ================== */
.overlay{position:fixed;inset:0;z-index:30;display:none;place-items:center;padding:4vh 4vw;
  background:color-mix(in srgb,var(--bg) 84%,transparent);backdrop-filter:blur(14px)}
.overlay.on{display:grid;animation:pop .26s var(--ease) both}
.sheet{width:min(1040px,100%);max-height:86vh;overflow:auto;background:var(--panel);border:1px solid var(--rule);
  border-radius:var(--r);box-shadow:var(--shadow);padding:clamp(16px,2.4vw,30px)}
.sheet h3{margin-top:0}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,220px),1fr));gap:10px}
.nav-card{text-align:start;width:100%;cursor:pointer;background:var(--panel2);border:1px solid var(--rule);
  border-radius:12px;padding:12px 13px;transition:.18s;font:inherit;color:inherit}
.nav-card:hover{border-color:var(--accent);transform:translateY(-2px)}
.nav-card.cur{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}
.nav-card .n{font-size:10.5px;font-weight:800;color:var(--ink3);font-variant-numeric:tabular-nums}
.nav-card .t{display:block;font-weight:800;margin-top:4px;line-height:1.5;font-size:14.5px}
.keys{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,220px),1fr));gap:9px 18px}
.keys div{display:flex;gap:9px;align-items:center;font-size:13.5px;color:var(--ink2)}
@media (prefers-reduced-motion:reduce){*{animation-duration:.001ms!important;transition-duration:.001ms!important}}
@media print{
  html,body{height:auto;overflow:visible;background:#fff;color:#000}
  header,footer,.overlay,.hint,.skip,body::before{display:none!important}
  main{padding:0;overflow:visible}
  .slide{display:grid!important;position:relative;inset:auto;box-shadow:none;border:0;border-bottom:2px solid #999;
    border-radius:0;break-after:page;page-break-after:always;background:#fff}
  .fig{background:#fff}
}
</style>
</head>
<body>
<a class="skip" href="#deck">انتقال إلى المحتوى</a>

<header>
  <div class="brand">
    <b>طبقات الأرض</b><span id="brand-sub">من القشرة إلى اللب</span>
  </div>
  <div class="gauge" aria-live="polite">
    <span class="dial" aria-hidden="true"><i id="dial"></i></span>
    <span>العمق حتى <b id="gauge-depth"><span class="num" lang="en">0</span></b> كم</span>
  </div>
  <div class="tools">
    <button class="btn" id="btn-index" aria-pressed="false">الفهرس<span class="k">ف</span></button>
    <button class="btn" id="btn-text" title="تكبير النص">نص+A</button>
    <button class="btn" id="btn-theme" aria-label="تبديل السمة"><span id="theme-label">ليلي</span><span class="k">ل</span></button>
    <button class="btn" id="btn-help" aria-pressed="false">؟</button>
  </div>
</header>

<main id="deck"></main>

<footer>
  <button class="btn" id="btn-prev">→ السابق</button>
  <div class="track" aria-hidden="true"><i id="bar"></i></div>
  <span class="counter" id="counter">—</span>
  <button class="btn" id="btn-next">التالي ←</button>
  <span class="hint"><kbd>→</kbd> السابق · <kbd>←</kbd> التالي · <kbd>مسافة</kbd> تالية · <kbd>ف</kbd> الفهرس · <kbd>ل</kbd> السمة · <kbd>م</kbd> ملء الشاشة</span>
</footer>

<div class="overlay" id="ov-index" role="dialog" aria-modal="true" aria-label="فهرس الشرائح">
  <div class="sheet"><h3>فهرس الشرائح</h3><div class="grid" id="index-list"></div></div>
</div>
<div class="overlay" id="ov-help" role="dialog" aria-modal="true" aria-label="اختصارات لوحة المفاتيح">
  <div class="sheet">
    <h3>اختصارات لوحة المفاتيح</h3>
    <div class="keys">
      <div><kbd>←</kbd> <kbd>مسافة</kbd> <kbd>Page↓</kbd> الشريحة التالية</div>
      <div><kbd>→</kbd> <kbd>Page↑</kbd> الشريحة السابقة</div>
      <div><kbd>م start</kbd> الشريحة الأولى</div>
      <div><kbd>نهاية</kbd> الشريحة الأخيرة</div>
      <div><kbd>1</kbd>–<kbd>9</kbd> القفز إلى شريحة</div>
      <div><kbd>ف</kbd> الفهرس</div>
      <div><kbd>ل</kbd> السمة الليلية/النهارية</div>
      <div><kbd>م</kbd> ملء الشاشة</div>
      <div><kbd>Esc</kbd> إغلاق النوافذ</div>
      <div><kbd>؟</kbd> هذه النافذة</div>
    </div>
    <p class="note" style="margin-bottom:0">العرض مصمَّم للقراءة من اليمين إلى اليسار: السهم الأيسر يتقدّم بك إلى الأسفل في العمق، والسهم الأيمن يرجعك إلى الأعلى.</p>
  </div>
</div>

<script>
"use strict";
/* ================================================================
   1) البيانات المرجعية — مصدر واحد لكل الأرقام في العرض كلِّه.
      الأعماق بالكيلومتر من سطح الأرض، والقيم المميّزة بـ«تقريبي»
      مأخوذة من النماذج الزلزالية (مثل PREM) لا من قياس مباشر.
   ================================================================ */
const DATA = {
  radius: 6371,            // نصف قطر الأرض المتوسط (كم)
  age: "4.54",             // مليار سنة
  bulkDensity: 5.51,       // غم/سم³
  kola: 12.262,            // أعمق حفرة حفرها الإنسان (كم)
  coreTemp: 5400,          // °س عند المركز (تقريبي)
  sunTemp: 5505,           // °س سطح الشمس
  centerPressure: 360,     // غيغاباسكال (تقريبي)
  cmbPressure: 135,        // غيغاباسكال عند حدّ الوشاح/اللب
  layers: [
    { id:"crust",  name:"القشرة",           lat:"crust",        top:0,    bottom:35,    color:"var(--c-crust)",
      state:"صلبة",       density:"2.7–3.0",  temp:"200–900",   comp:"بازلت وغرانيت (سيليكون وألومنيوم وحديد)" },
    { id:"mantle", name:"الوشاح",            lat:"mantle",       top:35,   bottom:2891,  color:"var(--c-mantle)",
      state:"صلبة تتدفأ ببطء", density:"3.3–5.5", temp:"1300–3800", comp:"بيروتيغ غنيّ بالأوليفين (حديد ومغنيسيوم وسيليكون)" },
    { id:"outer",  name:"اللب الخارجي",      lat:"outer core",   top:2891, bottom:5150,  color:"var(--c-outer)",
      state:"سائلة",      density:"9.9–12.2", temp:"3800–4400", comp:"حديد ونيكل سائلان + عناصر خفيفة" },
    { id:"inner",  name:"اللب الداخلي",     lat:"inner core",   top:5150, bottom:6371,  color:"var(--c-inner)",
      state:"صلبة",       density:"12.6–13.0", temp:"5000–5400", comp:"حديد ونيكل بلوريان" }
  ],
  boundaries: [
    { name:"انقطاع موهو",        lat:"Moho",        depth:35,   year:1909, who:"أندريا موسيفيتش",
      note:"الحدّ بين القشرة والوشاح؛ تقفّرٌ مفاجئ في سرعة الموجات الزلزالية." },
    { name:"انقطاع غوتنبرغ",     lat:"Gutenberg",   depth:2891, year:1914, who:"بنوا غوتنبرغ",
      note:"حدّ الوشاح/اللب الخارجي؛ هنا تتوقّف الموجات المستعرضة تماماً." },
    { name:"انقطاع ليمان",       lat:"Lehmann",     depth:5150, year:1936, who:"إنجي ليمان",
      note:"حدّ اللب الخارجي/اللب الداخلي؛ استُنتج من إشاراتٍ دقيقة في تسجيلات الزلازل." }
  ],
  tempCurve:    [[0,15],[35,300],[100,1300],[410,1700],[660,1900],[2891,3800],[5150,5200],[6371,5400]],
  pressureCurve:[[0,0],[35,1],[100,3],[410,13],[660,23],[2891,135],[5150,330],[6371,360]],
  // كثافات متوسطة تمثيلية — تُستعمل لتقدير الكتل فقط (مصرَّح به صراحةً في الشريحة)
  massDensity: { crust:2.8, mantle:4.5, outer:11.0, inner:12.8 }
};
/* كتل وحجوم كل طبقة تُحسب هنا، فلا تتناقح الأرقام المعروضة مع الهندسة */
(function computeFractions(){
  const a = DATA.radius, cube = r => r*r*r;
  const V = cube(a);
  DATA.layers.forEach(L=>{
    const rTop = a - L.top, rBot = a - L.bottom;
    L.thickness = L.bottom - L.top;
    L.volumePct   = 100 * (cube(rTop) - cube(rBot)) / V;
    L.massPct     = L.volumePct/100 * DATA.massDensity[L.id] * V /
                    (DATA.layers.reduce((s,X)=> s + (cube(a-X.top)-cube(a-X.bottom))/V*DATA.massDensity[X.id],0) * V) * 100;
  });
})();

/* ================================================================
   2) نصوص الشرائح
   ================================================================ */
const N = (v,d)=>`<span class="num" lang="en">${d===undefined?v:Number(v).toFixed(d)}</span>`;
const L = (t,e)=>`<span class="lat" lang="en">${e||t}</span>`;

const SLIDES = [
 { depth:0, kind:"cover", build:()=>`
   <div class="colstart">
     <div class="eyebrow">عرضٌ جيولوجيٌّ مصوَّر</div>
     <h1>طبقاتُ الأرض</h1>
     <p class="lead">من قشرةٍ أرقُّ من جلد التفاحة إلى قلبٍ من حديدٍ أدفأ من سطح الشمس —
       رحلةٌ إلى عمق ${N(6371)} كيلومتراً، بلا مغادرة السطح.</p>
     <div class="chips">
       <span class="chip"><s style="--c:var(--c-crust)"></s>القشرة</span>
       <span class="chip"><s style="--c:var(--c-mantle)"></s>الوشاح</span>
       <span class="chip"><s style="--c:var(--c-outer)"></s>اللب الخارجي</span>
       <span class="chip"><s style="--c:var(--c-inner)"></s>اللب الداخلي</span>
     </div>
   </div>
   <div class="colstart">
     <div class="stats">
       <div class="stat"><b>${N("4.54")}<small style="display:inline"> مليار سنة</small></b><span>عمر الأرض</span></div>
       <div class="stat"><b>${N(6371)}<small style="display:inline"> كم</small></b><span>نصف القطر المتوسط</span></div>
       <div class="stat"><b>${N(5.51)}<small style="display:inline"> غم/سم³</small></b><span>الكثافة الكلية</span></div>
       <div class="stat"><b>${N(4)}</b><span>طبقاتٌ رئيسية</span></div>
     </div>
     <div class="note">لا شيء في هذا العرض مبنيٌّ على مشاهداتٍ مباشرة: لم يحفر الإنسان قطُّ أعمق من
       <b>${N(DATA.kola,3)} كم</b>. كلُّ ما يلي مبنيٌّ على أربعة أدلةٍ غير مباشرة — سنراها في الشريحة العاشرة.</div>
   </div>` },

 { depth:12, eyebrow:"البداية", title:"لماذا نتحدّث عن مكانٍ لم نره قط؟", build:()=>`
   <div class="colstart">
     <p>أعمقُ حُفرَةٍ صنعها الإنسان هي بئر <b>كولا</b> فائقة العمق في روسيا، بلغت
       <b>${N(DATA.kola,3)} كم</b> فقط — أي نحو <b>${N((DATA.kola/DATA.radius*100).toFixed(2))}%</b> من نصف قطر الأرض.</p>
     <ul>
       <li>لو كانت الأرضُ كرةَ قدمٍ بقطر <b>${N(22)}</b> سم، لكان أعمقَ حفرٍ إنجازٍ بشريّاً أرقَّ من طبقةِ طلاء.</li>
       <li>قبل الوصول إلى الوشاح بقليل تصبح الحرارة فوق <b>${N(200)}</b> °س، والصخر يتصرّف كالعجينة — الحفرُ يستحيل.</li>
       <li>فلا يبقى إلا <strong>الاستدلال غير المباشر</strong>: الموجاتُ الزلزالية، الصخورُ المقتلعة من الأعماق،
           النيازك، ومختبراتُ الضغط العالي.</li>
     </ul>
     <div class="note"><b>الفكرة الحاكمة:</b> لا نرى باطن الأرض، لكنّا نسمعُه. الزلزالُ الكبير يبعث موجاتٍ
       تعبر الكوكب كلَّه في دقائق، فتعمل كما يعمل التصويرُ الطبي في الجسم.</div>
