/* ================================================================
   3) الرسومات — كلها SVG مبنيّ من DATA، بلا صور خارجية
   ================================================================ */
const SVGNS="http://www.w3.org/2000/svg";
function S(tag,attrs,txt){ const e=document.createElementNS(SVGNS,tag);
  for(const k in attrs) e.setAttribute(k,attrs[k]); if(txt!=null) e.textContent=txt; return e; }
function txt(x,y,s,o){ const t=S("text",Object.assign({x:x,y:y,fill:"currentColor","font-size":o&&o.size||12.5,
  "text-anchor":o&&o.anchor||"middle","font-family":"inherit","font-weight":o&&o.bold?800:400},o&&o.attrs||{}),s); return t; }
function root(w,h){ return S("svg",{viewBox:"0 0 "+w+" "+h,role:"img"}); }
function layerColor(id){ return DATA.layers.find(l=>l.id===id).color; }

/* — تفاحة: القشرة أغلظ قليلاً من قشرة التفاحة قياساً على حجم الأرض — */
function figApple(){
  const g=root(420,300); g.appendChild(txt(210,24,"لو كانت الأرضُ تفاحة", {size:13.5,bold:true}));
  const cx=210, cy=168, R=96;
  g.appendChild(S("circle",{cx:cx,cy:cy,r:R,fill:"var(--c-outer)",opacity:.28}));
  g.appendChild(S("circle",{cx:cx,cy:cy,r:R*0.545,fill:"var(--c-outer)",opacity:.85}));
  g.appendChild(S("circle",{cx:cx,cy:cy,r:R*0.192,fill:"var(--c-inner)"}));
  // قشرة التفاحة مبالَغ فيها عمداً حتى تُرى: 1.5% من نصف القطر بدل 0.55% الحقيقية
  g.appendChild(S("circle",{cx:cx,cy:cy,r:R,fill:"none",stroke:"var(--c-crust)","stroke-width":3}));
  g.appendChild(S("path",{d:"M"+cx+" "+cy,"fill":"none"}));
  g.appendChild(txt(cx,cy-R-8,"قشرةُ الأرض ≈ 1% من الحجم",{size:12,fill:"var(--ink2)"}));
  g.appendChild(txt(cx,cy+4,"المركز",{size:11,fill:"#3b2a12"}));
  const rows=[["اللب الداخلي",R*0.192,"var(--c-inner)"],["اللب الخارجي",R*0.545,"var(--c-outer)"],
              ["الوشاح",R*0.9,"var(--c-mantle)"],["القشرة",R,"var(--c-crust)"]];
  rows.forEach((r,i)=>{
    const y=252+i*0; // legend inline on one row
    const x=26+i*100;
    g.appendChild(S("rect",{x:x,y:250,width:10,height:10,rx:2.5,fill:r[2]}));
    const t=txt(x+15,259,r[0],{size:11,anchor:"start"}); t.setAttribute("text-anchor","start"); g.appendChild(t);
  });
  return g;
}

/* — المقطع الرأسي: قطاعاتٌ متداخلة تُظهر الأصداء الأربعة — */
function figCutaway(){
  const W=460,H=430,cx=160,cy=215,R=168,a=DATA.radius;
  const g=root(W,H);
  const s=R/a;
  const A0=-52, A1=52;                              // فتحة القطاع المواجهة لعمود التسميات
  const pt=(r,deg)=>{const t=deg*Math.PI/180;return [cx+r*Math.cos(t), cy+r*Math.sin(t)];};
  function sector(r0,r1,a0,a1){
