    const t=txt(cx+R+16,cy+4-(marks.indexOf(m)*0),null,{size:11,anchor:"start"});
    t.remove();
  });
  g.appendChild(txt(cx+R+22,cy-24,"السطح",{size:11,anchor:"start"}));
  g.appendChild(txt(cx+R+22,cy-6),"");
  g.appendChild(txt(cx+R+22,cy-6,"غوتنبرغ 2891 كم",{size:11,anchor:"start"}));
  g.appendChild(txt(cx+R+22,cy+14,"ليمان 5150 كم",{size:11,anchor:"start"}));
  g.appendChild(txt(cx,cy+R+22,"نصفُ قطر اللب الداخلي 1221.5 كم — نحو ثُلث نصف قطر الأرض",{size:11.5}));
  g.appendChild(txt(220,222,"الحرارةُ نحو 5400 °س، والضغطُ 360 غيغاباسكال",{size:11.5}));
  return g;
}

const FIGS={apple:figApple,cutaway:figCutaway,crust:figCrust,convection:figConvection,
            mantleZones:figMantleZones,shadow:figShadow,curves:figCurves,bars:figBars,
            field:figField,core:figCore};

/* ================================================================
   4) بناء الشرائح والجداول والمخططات
   ================================================================ */
const deck=document.getElementById("deck");
const figCap={
  apple:"قياسٌ تمثيلي: لو صُغِّرَت الأرض إلى تفاحة، لكانت القشرةُ أرقَّ من قشرتها. سماكةُ القشرة هنا مبالَغٌ فيها لترى.",
  cutaway:"مقطعٌ في الأرض يفتح قطاعاً واحداً فتبدو الأصداء الأربعة. الخطوطُ الرمادية حدودُ العمق.",
  crust:"القشرة المحيطية رقيقةٌ كثيفة تحت الماء؛ القاريةُ سميكةٌ خفيفة تحمل الجبال وجذورها.",
  convection:"الغلاف الصخري الصلب مكسورٌ إلى ألواح، تحته طبقةٌ لدنةٌ تتصرّف كسائلٍ لزج على مدى الجيولوجيا.",
  mantleZones:"أقسامُ الوشاح الثلاثة على مقياسٍ واحد للعمق، يُقرأ من اليمين إلى اليسار.",
  shadow:"منطقةُ ظلّ موجات P بين 103° و142°، وانعدامُ موجات S في اللب الخارجي — خلاصةُ الأدلة الزلزالية.",
  curves:"الحرارةُ والضغط دالا عمقٍ حتى 6371 كم (قيمٌ نموذجية تقريبية).",
  bars:"الأعمدة الداكنة نسبةُ الحجم (محسوبةٌ هندسياً من الأنصاف)، والفاتحةُ نسبةُ الكتلة بكثافةٍ متوسطة.",
  field:"تياراتُ الحمل في الحديد السائل تنشئ المجال المغناطيسي وتُخرج خطوطَه من القطبين.",
  core:"اللبّ الداخلي كرةٌ صلبة نصفُ قطرها 1221.5 كم عند مركزٍ ضغطُه 360 غيغاباسكال."
};
function buildDeck(){
  SLIDES.forEach((sl,i)=>{
    const sec=document.createElement("section");
    sec.className="slide"+(sl.kind==="cover"?" solo":"");
    sec.dataset.i=i; sec.dataset.depth=sl.depth;
    sec.setAttribute("role","group");
    sec.setAttribute("aria-label","شريحة "+(i+1)+(sl.title?": "+sl.title:""));
    sec.innerHTML='<div style="display:contents">'+sl.build()+'</div>';
    // eyebrow + title live outside the two columns so the grid stays clean
    if(sl.kind!=="cover"){
      const head=document.createElement("div");
      head.className="colstart";
      head.innerHTML='<div class="eyebrow">'+(sl.eyebrow||"شريحة")+'</div>'+
                     '<h2>'+sl.title+'</h2>'+
                     '<div class="head-extra"></div>';
      // move the two generated columns under a fresh wrapper with heading on top
      const body=document.createElement("div");
      body.style.display="contents";
      const kids=Array.prototype.slice.call(sec.childNodes);
      kids.forEach(k=>body.appendChild(k));
      sec.innerHTML=""; sec.appendChild(head); sec.appendChild(body);
    }
    deck.appendChild(sec);
  });
}
function fillTables(){
  const tb=document.querySelector("#layers-table tbody");
  if(tb) tb.innerHTML=DATA.layers.map(l=>
    '<tr><td><b><span class="swatch" style="--c:'+l.color+'"></span>'+l.name+'</b> '+
    '<span class="lat" lang="en" style="color:var(--ink3);font-size:12px">'+l.lat+'</span></td>'+
    '<td><span class="num" lang="en">'+l.top+'–'+l.bottom+'</span></td>'+
    '<td><span class="num" lang="en">'+l.thickness+'</span> كم</td>'+
    '<td>'+l.state+'</td><td><span class="num" lang="en">'+l.density+'</span></td></tr>').join("");
  const bt=document.querySelector("#bounds-table tbody");
  if(bt) bt.innerHTML=DATA.boundaries.map(b=>
    '<tr><td><b>'+b.name+'</b></td><td><span class="num" lang="en">'+b.depth+'</span> كم</td>'+
    '<td><span class="num" lang="en">'+b.year+'</span></td></tr>').join("");
  const tl=document.getElementById("tl-bounds");
  if(tl) tl.innerHTML=DATA.boundaries.map(b=>{
    const layer=DATA.layers.find(l=>b.depth>=l.top&&b.depth<=l.bottom)||DATA.layers[0];
    return '<li style="--c:'+layer.color+'"><span class="dot"><span class="num" lang="en">'+b.year+'</span></span>'+
           '<span><b>'+b.name+' <span class="lat" lang="en">('+b.lat+')</span></b>'+
           '<small>'+b.note+' — '+b.who+'.</small></span></li>';
  }).join("");
  const ct=document.querySelector("#curve-table tbody");
  if(ct) ct.innerHTML=DATA.tempCurve.map((p,i)=>
    '<tr><td><span class="num" lang="en">'+p[0]+'</span></td>'+
    '<td><span class="num" lang="en">'+p[1]+'</span></td>'+
    '<td><span class="num" lang="en">'+DATA.pressureCurve[i][1]+'</span></td></tr>').join("");
  const ft=document.querySelector("#frac-table tbody");
  if(ft) ft.innerHTML=DATA.layers.map(l=>
    '<tr><td><b><span class="swatch" style="--c:'+l.color+'"></span>'+l.name+'</b></td>'+
    '<td><span class="num" lang="en">'+l.volumePct.toFixed(1)+'%</span></td>'+
    '<td><span class="num" lang="en">'+l.massPct.toFixed(1)+'%</span></td></tr>').join("");
  const gl=document.getElementById("gloss");
  if(gl){ const G=[["القشرة","crust"],["الغلاف الصخري","lithosphere"],["الطبقة اللدنة","asthenosphere"],
      ["الوشاح","mantle"],["منطقة الانتقال","transition zone"],["انقطاع موهو","Moho"],
      ["انقطاع غوتنبرغ","Gutenberg discontinuity"],["انقطاع ليمان","Lehmann discontinuity"],
      ["اللب الخارجي","outer core"],["اللب الداخلي","inner core"],["المُولِّد الأرضي","geodynamo"],
      ["موجات أولية","P waves"],["موجات ثانوية","S waves"],["منطقة الظل","shadow zone"],
      ["البيروتيغ","peridotite"],["التدرج الحراري الأرضي","geothermal gradient"]];
    gl.innerHTML=G.map(x=>'<div><b>'+x[0]+'</b> <i class="lat" lang="en">'+x[1]+'</i></div>').join(""); }
}
function fillFigs(){
  document.querySelectorAll("[data-fig]").forEach(el=>{
    const kind=el.getAttribute("data-fig"), f=FIGS[kind];
    if(!f) return;
    el.innerHTML="";
    el.appendChild(f());
    const cap=document.createElement("figcaption");
    cap.textContent=figCap[kind]||"";
    el.appendChild(cap);
  });
}

/* ================================================================
   5) التنقّل والسمة والقياسات
   ================================================================ */
const root=document.documentElement, deckEl=document.getElementById("deck");
let cur=-1;
const fmt=n=>String(n);
function fitSlide(sec){
  sec.querySelectorAll(".colstart").forEach(c=>{
    c.style.fontSize="";
    let guard=0;
    while(sec.scrollHeight>sec.clientHeight+1 && guard++<14){
      const cur0=parseFloat(sec.querySelector(".colstart").style.fontSize||getComputedStyle(c).fontSize);
      const next=Math.max(12.5,Math.round((cur0-0.6)*10)/10);
      sec.querySelectorAll(".colstart").forEach(x=>x.style.fontSize=next+"px");
      if(next<=12.5) break;
    }
  });
}
function go(i,push){
  i=Math.max(0,Math.min(SLIDES.length-1,i));
  if(i===cur) return;
  const secs=deckEl.querySelectorAll(".slide");
  if(cur>=0) secs[cur].classList.remove("on");
  cur=i; const sec=secs[i]; sec.classList.add("on");
  const d=Number(sec.dataset.depth||0);
  document.getElementById("bar").style.width=(((i+1)/SLIDES.length)*100)+"%";
  document.getElementById("counter").textContent=fmt(i+1)+" / "+fmt(SLIDES.length);
  document.getElementById("gauge-depth").textContent=String(d);
  document.getElementById("dial").style.width=(d/DATA.radius*100)+"%";
  root.style.setProperty("--heat",(d/DATA.radius).toFixed(3));
  const sl=SLIDES[i];
  root.style.setProperty("--accent", sl.depth>=5150?"#c2410c":(sl.depth>=2891?"#b4530a":(sl.depth>=35?"#8a6d1f":"#7a5a2e")));
  document.querySelectorAll("#index-list .nav-card").forEach(c=>c.classList.toggle("cur",+c.dataset.i===i));
  document.getElementById("brand-sub").textContent=sl.title||"من القشرة إلى اللب";
  document.title=(sl.title||"طبقات الأرض")+" | عرض تقديمي";
  sec.querySelectorAll(".colstart").forEach(c=>c.scrollTop=0);
  fitSlide(sec);
  if(push!==false){ try{ history.replaceState(null,"","#"+(i+1)); }catch(e){ location.hash=i+1; } }
}
function overlay(el,on){ el.classList.toggle("on",!!on);
  const b=el.id==="ov-index"?document.getElementById("btn-index"):document.getElementById("btn-help");
  if(b) b.setAttribute("aria-pressed",on?"true":"false"); }
function buildIndex(){
  const box=document.getElementById("index-list");
  SLIDES.forEach((sl,i)=>{
    const b=document.createElement("button");
    b.className="nav-card"; b.type="button"; b.dataset.i=i;
    b.innerHTML='<span class="n">شريحة '+fmt(i+1)+' · عمق <span class="num" lang="en">'+sl.depth+'</span> كم</span>'+
                '<span class="t">'+(sl.title||"الصفحة الأولى")+'</span>';
    b.addEventListener("click",()=>{ go(i); overlay(document.getElementById("ov-index"),false); });
    box.appendChild(b);
  });
}
function setTheme(t){ root.dataset.theme=t;
  document.getElementById("theme-label").textContent=t==="light"?"ليلي":"نهاري";
  try{ localStorage.setItem("earth-deck-theme",t); }catch(e){} }
document.getElementById("btn-prev").addEventListener("click",()=>go(cur-1));
document.getElementById("btn-next").addEventListener("click",()=>go(cur+1));
document.getElementById("btn-index").addEventListener("click",()=>{
  const o=document.getElementById("ov-index"); overlay(o,!o.classList.contains("on"));
  overlay(document.getElementById("ov-help"),false); });
document.getElementById("btn-help").addEventListener("click",()=>{
  const o=document.getElementById("ov-help"); overlay(o,!o.classList.contains("on"));
  overlay(document.getElementById("ov-index"),false); });
document.getElementById("btn-theme").addEventListener("click",()=>setTheme(root.dataset.theme==="light"?"dark":"light"));
document.getElementById("btn-text").addEventListener("click",()=>{
  const now=parseFloat(getComputedStyle(root).getPropertyValue("--fs"))||1;
  const next=now>=1.22?1:Math.round((now+0.11)*100)/100;
  root.style.setProperty("--fs",next);
  try{ localStorage.setItem("earth-deck-fs",String(next)); }catch(e){}
  setTimeout(()=>{ const s=deckEl.querySelectorAll(".slide")[cur]; if(s) fitSlide(s); },30);
});
document.querySelectorAll(".overlay").forEach(o=>o.addEventListener("click",e=>{ if(e.target===o) overlay(o,false); }));
/* ملاحظة اتجاهٍ: في الـRTL السهمُ الأيسر يتقدّم، والأيمن يرجع */
document.addEventListener("keydown",e=>{
  if(e.metaKey||e.ctrlKey||e.altKey) return;
  const k=e.key;
  if(k==="Escape"){ const o=document.querySelector(".overlay.on"); if(o){ overlay(o,false); e.preventDefault(); } return; }
  if(k==="?"||(k==="/"&&e.shiftKey)){ document.getElementById("btn-help").click(); e.preventDefault(); return; }
  if(k==="ف"||k==="F"&&false){ document.getElementById("btn-index").click(); e.preventDefault(); return; }
  if(k==="ف"){ document.getElementById("btn-index").click(); e.preventDefault(); return; }
  if(k==="ل"||k==="L"){ document.getElementById("btn-theme").click(); e.preventDefault(); return; }
  if(k==="م"){ if(document.fullscreenElement){ document.exitFullscreen&&document.exitFullscreen(); }
    else document.documentElement.requestFullscreen&&document.documentElement.requestFullscreen(); e.preventDefault(); return; }
  if(k==="ArrowLeft"||k==="ArrowDown"||k===" "||k==="PageDown"){ go(cur+1); e.preventDefault(); return; }
  if(k==="ArrowRight"||k==="ArrowUp"||k==="PageUp"){ go(cur-1); e.preventDefault(); return; }
  if(k==="Home"){ go(0); e.preventDefault(); return; }
  if(k==="End"){ go(SLIDES.length-1); e.preventDefault(); return; }
  if(/^[1-9]$/.test(k)){ go(parseInt(k,10)-1); e.preventDefault(); }
});
let tx=null,ty=null;
deckEl.addEventListener("touchstart",e=>{ tx=e.touches[0].clientX; ty=e.touches[0].clientY; },{passive:true});
deckEl.addEventListener("touchend",e=>{
  if(tx===null) return;
  const dx=e.changedTouches[0].clientX-tx, dy=e.changedTouches[0].clientY-ty;
  if(Math.abs(dx)>68&&Math.abs(dx)>Math.abs(dy)*1.6) go(cur+(dx>0?1:-1));   // اسحب يساراً للتقدّم
  tx=ty=null;
},{passive:true});
let rt; addEventListener("resize",()=>{ clearTimeout(rt); rt=setTimeout(()=>{ const s=deckEl.querySelectorAll(".slide")[cur]; if(s) fitSlide(s); },150); });

/* إقلاع */
(function init(){
  buildDeck(); fillTables(); fillFigs(); buildIndex();
  let saved=null, savedFs=null;
  try{ saved=localStorage.getItem("earth-deck-theme"); savedFs=localStorage.getItem("earth-deck-fs"); }catch(e){}
  if(saved) setTheme(saved); else if(window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)").matches) setTheme("dark");
  if(savedFs) root.style.setProperty("--fs",savedFs);
  const start=parseInt((location.hash||"").replace(/[^0-9]/g,""),10);
  go(isNaN(start)||start<1?0:start-1,false);
})();
</script>
</body>
</html>
