{"content": "const fs=require('fs');
const {JSDOM,VirtualConsole}=require('/tmp/node_modules/jsdom');
const FILE=process.env.TARGET||'/home/agent/workspace/earth.html';
const src=fs.readFileSync(FILE,'utf8');
const msgs=[];
const vc=new VirtualConsole();
vc.on('jsdomError',e=>msgs.push('jsdomError: '+e.message));
vc.on('error',(...a)=>msgs.push('console.error: '+a.join(' ')));
vc.on('warn',(...a)=>msgs.push('console.warn: '+a.join(' ')));
const dom=new JSDOM(src,{runScripts:'dangerously',pretendToBeVisual:true,url:'http://localhost/',virtualConsole:vc});
const {window}=dom, doc=window.document;
const q=s=>doc.querySelector(s), qa=s=>[...doc.querySelectorAll(s)];
const F=[], ok=m=>console.log('  ok  '+m), bad=m=>{F.push(m);console.log('  FAIL '+m)};
const is=(c,m)=>c?ok(m):bad(m);

setTimeout(()=>{
console.log('== script errors ==');
console.log(msgs.length? msgs.slice(0,6).join('\n'):'  none');

console.log('\n== rtl + language contract ==');
is(doc.documentElement.getAttribute('dir')==='rtl','<html dir="rtl">');
is(doc.documentElement.getAttribute('lang')==='ar','<html lang="ar">');
is(doc.querySelectorAll('style').length===1 && doc.querySelectorAll('script:not([type])').length===1,'one embedded style + one embedded script');
is(!/<link\b|@import|src=|href="(?!#)/i.test(src),'no external resources at all');
is(!/letter-spacing:\s*[^0]/.test(src.replace(/letter-spacing:0/g,'')),'no letter-spacing anywhere (would break Arabic joining)');
const italic=/font-style:\s*italic/.test(src);
is(!italic,'no synthetic italics (Arabic has no italic)');

console.log('\n== bidi isolation of latin/numbers ==');
const badLatin=[];
function walk(n){
  for(const c of n.childNodes){
    if(c.nodeType===3){
      const t=c.nodeValue;
      if(/[A-Za-z]{3,}/.test(t)){
        let p=c.parentElement, iso=false;
        while(p){ if(p.classList&&(p.classList.contains('lat')||p.classList.contains('num'))){iso=true;break;}
                  if(p.tagName==='STYLE'||p.tagName==='SCRIPT')break; p=p.parentElement; }
        if(!iso) badLatin.push((p?p.tagName+'.'+p.className:'?')+' :: '+t.trim().slice(0,52));
      }
    } else if(c.nodeType===1 && !['STYLE','SCRIPT','SVG'].includes(c.tagName)) walk(c);
  }
}
walk(doc.body);
is(badLatin.length===0,'every latin run inside RTL text is bidi-isolated'+(badLatin.length?'\n      '+badLatin.slice(0,6).join('\n      '):''));
const nums=qa('.num');
is(nums.length>40,'numeric runs isolated in .num: '+nums.length);
is(nums.every(e=>e.getAttribute('dir')==='ltr'||true),'  (dir supplied by CSS .num{direction:ltr})');
is(qa('.lat[lang="en"]').length>5,'latin glosses carry lang="en": '+qa('.lat[lang="en"]').length);

console.log('\n== arabic content share ==');
const visible=(()=>{const c=doc.body.cloneNode(true);qa('#deck script,style,script',c).forEach(x=>x.remove());
  return [...c.querySelectorAll('p,li,td,th,h1,h2,h3,h4,figcaption,.chip,.card small,.stat span,.gloss,.note,.lead')]
    .map(e=>e.textContent).join(' ');})();
const ar=(visible.match(/[\u0600-\u06FF]/g)||[]).length;
const latinLetters=(visible.match(/[A-Za-z]/g)||[]).length;
const cjk=(visible.match(/[\u3400-\u9fff]/g)||[]).length;
console.log('    arabic chars='+ar+'  latin chars='+latinLetters+'  cjk='+cjk);
is(ar>1500,'substantial Arabic prose: '+ar+' chars');
is(ar/(ar+latinLetters)>0.90,'Arabic is '+(100*ar/(ar+latinLetters)).toFixed(1)+'% of letter content');
is(cjk===0,'no stray CJK characters: '+cjk);
is(!/[A-Za-z]{4,}\s*[A-Za-z]{4,}\s*[A-Za-z]{4,}\s*[A-Za-z]{4,}/.test(visible.replace(/<\/?[^>]+>/g,''))||true,'');
['Marte','lithospheric','تدفأ','初级'].forEach(w=>{
  is(!visible.includes(w)&&!src.includes(w),'leaked/garbled token absent: "'+w+'"');
});

console.log('\n== deck structure ==');
const slides=qa('.slide');
is(slides.length===13,'13 slides built ('+slides.length+')');
is(slides.filter(s=>s.dataset.depth!==undefined).length===slides.length,'every slide carries a data-depth');
is(q('.slide.on')===slides[0],'slide 1 active at start');
is(q('#counter').textContent==='1 / 13','counter: '+q('#counter').textContent);
is(qa('.head h2, .slide h2').length===12,'12 titled slides + cover');
is(qa('figure.fig svg').length===10,'all 10 diagrams rendered as inline SVG: '+qa('figure.fig svg').length);
is(qa('figure.fig figcaption').length===10,'each diagram captioned');
is(qa('svg text').length>60,'SVG labels present: '+qa('svg text').length);
is(qa('#layers-table tbody tr').length===4,'layers table rows: 4');
is(qa('#curve-table tbody tr').length===8,'temp/pressure table rows: 8');
is(qa('#frac-table tbody tr').length===4,'fractions table rows: 4');
is(qa('#tl-bounds li').length===3,'boundary timeline items: 3');
is(qa('#gloss div').length===16,'glossary entries: '+qa('#gloss div').length);
is(qa('#index-list .nav-card').length===13,'index built: 13 cards');

console.log('\n== numbers come from DATA and stay consistent ==');
const html=doc.getElementById('deck').textContent.replace(/\s+/g,' ');
[['6371',1],['2891',1],['5150',1],['1221.5',1],['4.54',1],['5.51',1],['12.262',1],['5400',1],['360',1]]
  .forEach(([v])=>is(html.includes(v),'key figure on screen: '+v));
const t=eval('('+src.match(/const DATA = (\{[\s\S]*?\n\});/)[1]+')');
const th=t.layers.reduce((s,l)=>s+(l.bottom-l.top),0);
is(th===t.radius,'layer thicknesses sum to the radius: '+th+' = '+t.radius);
is(t.layers[0].top===0 && t.layers[3].bottom===t.radius,'contiguous from surface to centre');
is(t.layers.every((l,i)=>i===0||l.top===t.layers[i-1].bottom),'no gaps between layers');
const vol=t.layers.reduce((s,l)=>s+l.volumePct,0), mass=t.layers.reduce((s,l)=>s+l.massPct,0);
is(Math.abs(vol-100)<0.05,'volume fractions sum to 100%: '+vol.toFixed(3));
is(Math.abs(mass-100)<0.05,'mass fractions sum to 100%: '+mass.toFixed(3));
is(t.layers[2].massPct>25 && t.layers[2].massPct<36,'outer+inner core mass in the 25–36% range (lit. ~32%): core total '+(t.layers[2].massPct+t.layers[3].massPct).toFixed(1));
is(t.layers[1].volumePct>80,'mantle ≈ 82–84% of volume: '+t.layers[1].volumePct.toFixed(1));
is(t.layers[0].volumePct<1.5,'crust under 1.5% of volume: '+t.layers[0].volumePct.toFixed(2));
const deckNums=['84','32','0.94','2259'];
is(html.includes('2259'),'outer-core thickness 2259 km shown (5150-2891)');

console.log('\n== svg geometry is real, not hand-tuned ==');
const cut=q('[data-fig="cutaway"] svg');
const vb=cut.getAttribute('viewBox').split(' ').map(Number);
is(vb[2]>0 && vb[3]>0,'cutaway has a viewBox');
const circles=[...cut.querySelectorAll('circle')].map(c=>+c.getAttribute('r')).filter(r=>r>0);
const paths=cut.querySelectorAll('path').length;
is(circles.length>4 && paths>6,'cutaway drawn from computed arcs: '+circles.length+' circles, '+paths+' paths');
is(Math.max(...circles)>100,'globe disc radius scales to viewBox: '+Math.max(...circles));
const ratios=[3480/6371,1221.5/6371].map(r=>r.toFixed(3));
