<script>
/* ================================================================
   0. no dependencies: everything below is self-contained
   ================================================================ */
%%CORE%%

/* ================================================================
   1. build slides from the two markdown sources
   ================================================================ */
(function () {
  'use strict';
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };

  var srcEn = $('#md-en').textContent.replace(/^\n/, '');
  var srcZh = $('#md-zh').textContent.replace(/^\n/, '');
  var EN = toSections(srcEn), ZH = toSections(srcZh);
  var warn = $('#warn');
  function shout(m) { warn.textContent = m; warn.style.display = 'block'; setTimeout(function () { warn.style.display = 'none'; }, 6500); }

  if (EN.length !== ZH.length) {
    shout('Source mismatch: ' + EN.length + ' EN sections vs ' + ZH.length + ' ZH sections — slides may be misaligned.');
  }
  var N = Math.min(EN.length, ZH.length);

  /* section kind drives the accent colour */
  function kindOf(title) {
    var t = (title || '');
    if (/sunset|日落|twilight|暮光/i.test(t)) return 'sunset';
    if (/Level 1|第一层/.test(t)) return 'l1';
    if (/Level 2|第二层/.test(t)) return 'l2';
    if (/Level 3|第三层/.test(t)) return 'l3';
    return null;
  }
  var parent = 'l2', parentTrail = { en: '', zh: '' };
  var slides = [];
  for (var i = 0; i < N; i++) {
    var e = EN[i], z = ZH[i];
    var k = kindOf(e.title) || kindOf(z.title);
    if (e.lvl === 1) {
      slides.push({ cover: true, kind: 'l2', en: e, zh: z, trailEn: '', trailZh: '' });
      continue;
    }
    if (e.lvl === 2) { parent = k || 'l2'; parentTrail = { en: e.title || '', zh: z.title || '' }; }
    slides.push({
      cover: false,
      kind: e.lvl === 2 ? parent : (parent === 'l3' ? 'l3' : parent),
      en: e, zh: z,
      trailEn: parentTrail.en, trailZh: parentTrail.zh
    });
  }
  slides.forEach(function (s) { var kk = kindOf(s.en.title); if (kk) s.kind = kk; });

  var stripHr = function (h) { return (h || '').replace(/(?:\s*<hr>\s*)+$/, ''); };
  var plain = function (t) { return (t || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim(); };

  /* ---------- render the deck ---------- */
  var deck = $('#deck'), frag = document.createDocumentFragment();
  slides.forEach(function (s, idx) {
    var sec = document.createElement('section');
    sec.className = 'slide' + (s.cover ? ' cover' : '');
    sec.dataset.i = idx;
    sec.setAttribute('role', 'group');
    sec.setAttribute('aria-label', (s.en.title || 'Cover') + ' / ' + (s.zh.title || ''));

    var bodyEn = s.cover
      ? '<div class="tag"><span><em>EN</em> · English</span><span>' + (idx + 1) + ' / ' + N + '</span></div>' +
        '<div class="body"><div class="big">' + esc(s.en.title) + '</div>' + stripHr(s.en.html) + '</div>'
      : '<div class="tag"><span><em>EN</em> · English</span><span>' + (idx + 1) + ' / ' + N + '</span></div>' +
        (s.trailEn && s.trailEn !== s.en.title ? '<div class="eyebrow">' + esc(s.trailEn) + '</div>' : '') +
        '<h2>' + esc(s.en.title) + '</h2>' +
        '<div class="body">' + stripHr(s.en.html) + '</div>';

    var bodyZh = s.cover
      ? '<div class="tag"><span><em>中文</em> · Chinese</span><span>' + (idx + 1) + ' / ' + N + '</span></div>' +
        '<div class="body"><div class="big">' + esc(s.zh.title) + '</div>' + stripHr(s.zh.html) + '</div>'
      : '<div class="tag"><span><em>中文</em> · Chinese</span><span>' + (idx + 1) + ' / ' + N + '</span></div>' +
        (s.trailZh && s.trailZh !== s.zh.title ? '<div class="eyebrow">' + esc(s.trailZh) + '</div>' : '') +
        '<h2>' + esc(s.zh.title) + '</h2>' +
        '<div class="body">' + stripHr(s.zh.html) + '</div>';

    sec.innerHTML =
      '<div class="col en" lang="en">' + bodyEn + '</div>' +
      '<div class="col zh" lang="zh-Hans">' + bodyZh + '</div>' +
      (s.cover ? '<span class="mark" aria-hidden="true"></span>' : '');
    frag.appendChild(sec);
  });
  deck.appendChild(frag);

  /* ---------- overview / TOC ---------- */
  var ovList = $('#ov-list');
  slides.forEach(function (s, idx) {
    var b = document.createElement('button');
    b.className = 'card'; b.type = 'button'; b.dataset.i = idx;
    b.innerHTML = '<span class="n">' + String(idx + 1).padStart(2, '0') + ' · ' +
      (s.cover ? 'COVER' : 'L' + s.en.lvl) + '</span>' +
      '<div class="t">' + esc(s.en.title || '—') + '</div>' +
      '<div class="z">' + esc(s.zh.title || '—') + '</div>';
    b.addEventListener('click', function () { go(idx); overlay($('#ov-grid'), false); });
    ovList.appendChild(b);
  });

  /* ---------- state ---------- */
  var cur = -1;
  var LANGS = ['both', 'en', 'zh'];
  var html = document.documentElement;

  function fitCol(col) {
    var body = $('.body', col); if (!body) return;
    body.style.fontSize = '';
    var guard = 0;
    var min = 11.5;
    while (col.scrollHeight > col.clientHeight + 1 && guard++ < 18) {
      var px = parseFloat(body.style.fontSize || getComputedStyle(body).fontSize);
      var next = Math.max(min, Math.round((px - 0.6) * 10) / 10);
      body.style.fontSize = next + 'px';
      if (next <= min) break;
    }
  }

  function go(i, push) {
    i = Math.max(0, Math.min(N - 1, i));
    if (i === cur) { return; }
    var slidesEls = $$('.slide', deck);
    if (cur >= 0) slidesEls[cur].classList.remove('on');
    cur = i;
    var s = slides[i], el = slidesEls[i];
    el.classList.add('on');
    html.dataset.kind = s.kind || 'l2';
    $$('.col', el).forEach(function (c) { c.scrollTop = 0; fitCol(c); });
    $('#counter').textContent = String(i + 1).padStart(2, '0') + ' / ' + String(N).padStart(2, '0');
    $('#bar').style.width = ((i + 1) / N * 100) + '%';
    $$('#ov-list .card').forEach(function (c) { c.classList.toggle('cur', +c.dataset.i === i); });
    if (push !== false) { try { history.replaceState(null, '', '#' + (i + 1)); } catch (e) { location.hash = i + 1; } }
    document.title = (s.en.title || 'Sky') + ' · ' + (s.zh.title || '') + ' — bilingual deck';
  }

  /* ---------- overlays ---------- */
  function overlay(el, on) {
