  /* ---------- language + theme ---------- */
  var lang = 'both';
  function setLang(l) {
    lang = l; html.dataset.lang = l;
    $('#lang-label').textContent = l === 'en' ? 'English' : l === 'zh' ? '中文' : 'EN + 中文';
    $('#btn-lang').setAttribute('aria-pressed', l === 'both' ? 'false' : 'true');
    if (cur >= 0) { var el = $$('.slide', deck)[cur]; $$('.col', el).forEach(function (c) { c.scrollTop = 0; fitCol(c); }); }
  }
  function setTheme(t) {
    t = (t === 'night' || t === 'twilight') ? 'night' : 'day';   /* 'twilight' = legacy value */
    html.dataset.theme = t;
    var goingTo = t === 'day' ? 'Night Mode' : 'Day Mode';       /* label names the mode you get */
    $('#theme-label').textContent = goingTo;
    $('#btn-theme').setAttribute('aria-label', 'Switch to ' + goingTo);
    try { localStorage.setItem('skydeck-theme', t); } catch (e) { }
  }
  /* deterministic star field — pure CSS gradients, no images, no assets */
  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      var x = Math.imul(a ^ a >>> 15, 1 | a);
      x = x + Math.imul(x ^ x >>> 7, 61 | x) ^ x;
      return ((x ^ x >>> 14) >>> 0) / 4294967296;
    };
  }
  function starField(el, count, seed, cfg) {
    if (!el) return;
    var rnd = mulberry32(seed), g = [];
    for (var i = 0; i < count; i++) {
      var x = (rnd() * 100).toFixed(2), y = (rnd() * 100).toFixed(2);
      var r = (cfg.r0 + rnd() * cfg.r1).toFixed(2);
      var a = (cfg.a0 + rnd() * cfg.a1).toFixed(2);
      var tint = rnd() < .12 ? (rnd() < .5 ? '212,226,255' : '255,236,214') : '255,255,255';
      g.push('radial-gradient(circle at ' + x + '% ' + y + '%,rgba(' + tint + ',' + a + ') 0,' +
        'rgba(' + tint + ',' + a + ') ' + r + 'px,rgba(' + tint + ',0) ' + (Number(r) + .7).toFixed(2) + 'px)');
    }
    el.style.backgroundImage = g.join(',');
  }

  /* ---------- wire up ---------- */
  $('#brand-en').textContent = plain(EN[0] && EN[0].title);
  $('#brand-zh').textContent = plain(ZH[0] && ZH[0].title);
  document.title = plain(EN[0] && EN[0].title) + ' · ' + plain(ZH[0] && ZH[0].title);

  $('#btn-prev').addEventListener('click', function () { go(cur - 1); });
  $('#btn-next').addEventListener('click', function () { go(cur + 1); });
  $('#btn-grid').addEventListener('click', function () { var o = $('#ov-grid'); overlay(o, !o.classList.contains('on')); overlay($('#ov-help'), false); });
  $('#btn-help').addEventListener('click', function () { var o = $('#ov-help'); overlay(o, !o.classList.contains('on')); overlay($('#ov-grid'), false); });
  $('#btn-lang').addEventListener('click', function () { setLang(LANGS[(LANGS.indexOf(lang) + 1) % LANGS.length]); });
  $('#btn-theme').addEventListener('click', function () { setTheme(html.dataset.theme === 'day' ? 'night' : 'day'); });
  $$('.overlay').forEach(function (o) { o.addEventListener('click', function (e) { if (e.target === o) overlay(o, false); }); });

  document.addEventListener('keydown', function (e) {
