    if (k === '?' || (k === '/' && e.shiftKey)) { $('#btn-help').click(); e.preventDefault(); return; }
    if (k === 'o' || k === 'O') { $('#btn-grid').click(); e.preventDefault(); return; }
    if (k === 'l' || k === 'L') { $('#btn-lang').click(); e.preventDefault(); return; }
    if (k === 'd' || k === 'D') { $('#btn-theme').click(); e.preventDefault(); return; }
