private class UiThrottle(private val intervalMs: Long = UI_UPDATE_INTERVAL_MS) {
    private var lastUpdateTimeMs = 0L
    fun shouldUpdate(): Boolean {
        val now = System.currentTimeMillis()
        if (now - lastUpdateTimeMs <= intervalMs) return false
        lastUpdateTimeMs = now
        return true
    }
}
