```kotlin
private suspend fun AwaitPointerEventScope.awaitLockDrag(
    downY: Float,
    isRecordingLocked: () -> Boolean,
    lockThresholdPx: Float,
    onToggleVideo: () -> Unit,
    onDragOffset: (Float) -> Unit,
    onLockRecording: () -> Unit,
) {
    while (true) {
        val pointer = awaitPointerEvent().changes.firstOrNull()
        if (pointer == null || !pointer.pressed) {
            if (!isRecordingLocked()) onToggleVideo()
            onDragOffset(0f)
            break
        }
        if (!isRecordingLocked()) {
            val offset = (downY - pointer.position.y).coerceAtLeast(0f)
            onDragOffset(offset)
            if (offset >= lockThresholdPx) {
                onLockRecording()
                onDragOffset(0f)
            }
        }
        pointer.consume()
    }
}
```
