            ContextCompat.registerReceiver(
                context,
                activity.getRecordingReceiver(),
                IntentFilter(ACTION_TOGGLE_VIDEO),
                ContextCompat.RECEIVER_NOT_EXPORTED,
            )
        }
    }

    fun attachSensorListeners() {
        sensorCapture.setOnSensorImageAvailableListener(SensorFrameRelay(livePreview))
        sensorCapture.setOnMetadataAvailableListener(object : SensorCapture.OnMetadataAvailableListener {
            override fun onMetadataAvailable(
                iso: Int,
                exposureTimeNs: Long,
                dynamicBlackLevel: FloatArray?,
                awbGains: FloatArray?,
                colorMatrix: FloatArray?,
                intrinsics: FloatArray?,
                flickerHz: Int,
            ) {
                livePreview.setIso(iso)
                livePreview.setExposureTime(exposureTimeNs)

                if (flickerHz != currentFlickerHz) {
                    currentFlickerHz = flickerHz
                    val manualSnapshot = manualExposureTimeNs
                    if (flickerHz > 0 && manualSnapshot > 0) {
                        val period = flickerPeriodNs(flickerHz)
                        val snapped = snapToMultipleOf(manualSnapshot, period)
                        if (snapped != manualSnapshot) {
                            manualExposureTimeNs = snapped
                            sensorCapture.setManualExposureTime(snapped)
                        }
                    }
                }

                if (metadataUiThrottle.shouldUpdateUi()) {
                    currentIso = iso
                    currentExposureTimeNs = exposureTimeNs
                }

                livePreview.setBlackLevelPattern(
                    dynamicBlackLevel ?: floatArrayOf(
                        DEFAULT_BLACK_LEVEL, DEFAULT_BLACK_LEVEL, DEFAULT_BLACK_LEVEL, DEFAULT_BLACK_LEVEL,
                    )
                )
                if (awbGains != null && !isRecording) {
                    livePreview.setWbGains(
                        maxOf(MIN_WB_GAIN, awbGains[0]),
                        maxOf(MIN_WB_GAIN, awbGains[1]),
                        maxOf(MIN_WB_GAIN, awbGains[2]),
                    )
                }
                if (colorMatrix != null) {
                    livePreview.setColorMatrix(colorMatrix)
                }
            }
        })
    }

    fun openSelectedCamera(rawSurface: Surface): Boolean {
        if (openedCameraId == cameraKey(selectedCameraId, selectedPhysicalId) && lastOpenedSurface === rawSurface) {
            return false
        }
        sensorCapture.closeCamera()
        livePreview.resetForCameraSwitch()
        attachSensorListeners()

        val effectiveId = selectedPhysicalId ?: selectedCameraId
        applySensorParameters(effectiveId, cameraInfoFor(selectedCameraId, selectedPhysicalId))

        sensorCapture.openCamera(selectedCameraId, selectedPhysicalId, rawSurface)
        openedCameraId = cameraKey(selectedCameraId, selectedPhysicalId)
        lastOpenedSurface = rawSurface

        applyManualControls()
        return true
    }

    LaunchedEffect(hasCameraPermission, selectedCameraId, selectedPhysicalId, lifecycleEvent, rawPreviewSurface) {
        if (!hasCameraPermission || selectedCameraId.isEmpty()) return@LaunchedEffect

        when (lifecycleEvent) {
            Lifecycle.Event.ON_PAUSE, Lifecycle.Event.ON_STOP -> releaseCameraForBackground()

            Lifecycle.Event.ON_RESUME, Lifecycle.Event.ON_START -> {
                registerRecordingReceiver()
                glSurfaceView.onResume()

                val rawSurface = rawPreviewSurface
                if (rawSurface != null && openSelectedCamera(rawSurface)) {
                    val window = context.findActivity()?.window ?: return@LaunchedEffect
                    perfOptimizer.enableSustainedPerformanceMode(window)
                    perfOptimizer.startPerformanceSession(activeThreads)
                }
            }

            else -> {}
        }
    }

    LaunchedEffect(hasCameraPermission) {
        if (!hasCameraPermission) return@LaunchedEffect

        cameras = cameraProvider.getAvailableCameras()
        if (cameras.isNotEmpty() && selectedCameraId.isEmpty()) {
            selectedCameraId = cameras.first().id
            selectedPhysicalId = cameras.find { it.zoomLabel == "1x" }?.physicalId ?: cameras.first().physicalId
        }
    }

