private class UiUpdateThrottle(private val intervalMs: Long = UI_UPDATE_INTERVAL_MS) {
    private var lastUpdateMs = 0L

    fun shouldUpdateUi(): Boolean {
        val now = System.currentTimeMillis()
        if (now - lastUpdateMs <= intervalMs) return false
        lastUpdateMs = now
        return true
    }
}

private class SensorFrameRelay(private val livePreview: LivePreview) : SensorCapture.OnSensorImageAvailableListener {
    override fun onSensorImageAvailable(reader: ImageReader) {
        try {
            val image = reader.acquireNextImage()
            if (image != null) {
                livePreview.updateSensorImage(image)
            }
        } catch (e: Exception) {
            Log.e(LOG_TAG, "live Error acquiring image", e)
        }
    }
}

private fun flickerPeriodNs(flickerHz: Int): Long =
    if (flickerHz == FLICKER_50HZ) FLICKER_50HZ_PERIOD_NS else FLICKER_60HZ_PERIOD_NS

private fun snapToMultipleOf(valueNs: Long, periodNs: Long): Long =
    maxOf(1L, (valueNs.toDouble() / periodNs).roundToInt() * periodNs)

private fun newVideoFile(context: Context, prefix: String): File =
    File(
        context.getExternalFilesDir(null),
        "${prefix}${System.currentTimeMillis()}.$VIDEO_FILE_EXTENSION"
    )

private fun chooseRecordableEglConfig(egl: EGL14, display: EGLDisplay): EGLConfig {
    val attribList = intArrayOf(
        EGL14.EGL_RED_SIZE, 8,
        EGL14.EGL_GREEN_SIZE, 8,
        EGL14.EGL_BLUE_SIZE, 8,
        EGL14.EGL_ALPHA_SIZE, 8,
        EGL14.EGL_RENDERABLE_TYPE, EGL14.EGL_OPENGL_ES2_BIT,
        EGLExt.EGL_RECORDABLE_ANDROID, 1,
        EGL14.EGL_NONE,
    )
    val configs = arrayOfNulls<EGLConfig>(1)
    val numConfigs = IntArray(1)
    egl.eglChooseConfig(display, attribList, configs, 1, numConfigs)
    return configs[0] ?: throw RuntimeException("No recordable EGL config found")
}

private suspend fun AwaitPointerEventScope.awaitShutterGesture(
    isRecording: () -> Boolean,
    isRecordingLocked: () -> Boolean,
    lockThresholdPx: Float,
    longPressTimeoutMs: () -> Long,
    onToggleVideo: () -> Unit,
    onTakePhoto: () -> Unit,
    onDragOffset: (Float) -> Unit,
    onLockRecording: () -> Unit,
) {
    while (true) {
        val down = awaitFirstDown()

        if (isRecording()) {
            val up = waitForUpOrCancellation()
            if (up != null) {
                onToggleVideo()
            }
            continue
        }

        val upChange = withTimeoutOrNull(longPressTimeoutMs()) {
            while (true) {
                val pointer = awaitPointerEvent().changes.firstOrNull() ?: break
                if (pointer.pressed) {
                    pointer.consume()
                } else {
                    return@withTimeoutOrNull pointer
                }
            }
            null
        }

        if (upChange != null) {
            if (!isRecording()) {
                onTakePhoto()
            }
        } else {
            if (!isRecording()) {
                onToggleVideo()
            }
            awaitRecordingLockDrag(
                downY = down.position.y,
                isRecordingLocked = isRecordingLocked,
                lockThresholdPx = lockThresholdPx,
                onToggleVideo = onToggleVideo,
                onDragOffset = onDragOffset,
                onLockRecording = onLockRecording,
            )
        }
    }
}

private suspend fun AwaitPointerEventScope.awaitRecordingLockDrag(
    downY: Float,
    isRecordingLocked: () -> Boolean,
    lockThresholdPx: Float,
    onToggleVideo: () -> Unit,
    onDragOffset: (Float) -> Unit,
    onLockRecording: () -> Unit,
) {
    while (true) {
        val pointer = awaitPointerEvent().changes.firstOrNull()
        if (pointer == null || !pointer.pressed) {
            if (!isRecordingLocked()) {
                onToggleVideo()
            }
            onDragOffset(0f)
            break
        }

        if (!isRecordingLocked()) {
            val dragOffset = (downY - pointer.position.y).coerceAtLeast(0f)
            onDragOffset(dragOffset)
            if (dragOffset >= lockThresholdPx) {
                onLockRecording()
                onDragOffset(0f)
            }
        }
        pointer.consume()
    }
}

private suspend fun AwaitPointerEventScope.awaitPressAndRelease(
    onPressed: () -> Unit,
    onReleased: () -> Unit,
) {
    while (true) {
        awaitFirstDown()
        onPressed()
        waitForUpOrCancellation()
        onReleased()
    }
}

