fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "--"

    if (exposureTimeNs >= 333_333_333L) {
        val tenths = (exposureTimeNs + 50_000_000L) / 100_000_000L
        return if (tenths % 10L == 0L) {
            "${tenths / 10L}s"
        } else {
            "${tenths / 10L}.${tenths % 10L}s"
        }
    }

    val denominator = (NS_PER_SECOND + exposureTimeNs / 2L) / exposureTimeNs
    return "1/${denominator}s"
}

fun processCaptureInBackground(
    context: Context,
    byteBuffer: ByteBuffer,
    width: Int,
    height: Int,
    timestamp: Long,
    readbackTime: Long,
    shutterStartTime: Long,
    metadata: CaptureMetadata,
) {
    try {
        val bitmapStartMs = System.currentTimeMillis()
        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        byteBuffer.rewind()
        bitmap.copyPixelsFromBuffer(byteBuffer)
        val bitmapCopyMs = System.currentTimeMillis()

        saveBitmapToGallery(context, bitmap, metadata, shutterStartTime, readbackTime, bitmapCopyMs - bitmapStartMs)
        bitmap.recycle()

        val writeDoneMs = System.currentTimeMillis()
        Log.d(
            LOG_TAG,
            "[PERF_CAPTURE] res=${width}x${height} total=${writeDoneMs - shutterStartTime}ms " +
                "wait=${bitmapStartMs - shutterStartTime}ms copy=${bitmapCopyMs - bitmapStartMs}ms " +
                "write=${writeDoneMs - bitmapCopyMs}ms readback=${readbackTime}ms"
        )
    } catch (e: Exception) {
        Log.e(LOG_TAG, "capture Background capture failed: ${e.message}", e)
    }
}

fun saveBitmapToGallery(
    context: Context,
    bitmap: Bitmap,
    metadata: CaptureMetadata,
    shutterStart: Long,
    readbackTime: Long,
    bitmapTime: Long,
) {
    val contentValues = ContentValues().apply {
        val now = System.currentTimeMillis()
        put(MediaStore.MediaColumns.DISPLAY_NAME, "$IMAGE_FILE_PREFIX${metadata.timestamp}.jpg")
        put(MediaStore.MediaColumns.MIME_TYPE, IMAGE_MIME_TYPE)
        put(MediaStore.MediaColumns.RELATIVE_PATH, IMAGE_RELATIVE_PATH)
        put(MediaStore.MediaColumns.DATE_TAKEN, metadata.timestamp)
        put(MediaStore.MediaColumns.DATE_ADDED, now / MS_PER_SECOND)
        put(MediaStore.MediaColumns.DATE_MODIFIED, now / MS_PER_SECOND)
        put(MediaStore.MediaColumns.WIDTH, bitmap.width)
        put(MediaStore.MediaColumns.HEIGHT, bitmap.height)
        put(MediaStore.Images.ImageColumns.ORIENTATION, 0)
        put(MediaStore.MediaColumns.IS_PENDING, 1)
    }

    val uri = context.contentResolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, contentValues)
    uri?.let { imageUri ->
        try {
            val encodeStartMs = System.currentTimeMillis()
            context.contentResolver.openOutputStream(imageUri)?.use { outputStream ->
                bitmap.compress(Bitmap.CompressFormat.JPEG, JPEG_QUALITY, outputStream)
            }
            val encodeDoneMs = System.currentTimeMillis()

            context.contentResolver.openFileDescriptor(imageUri, "rw")?.use { pfd ->
                val exif = ExifInterface(pfd.fileDescriptor)
                val exposureTime = if (metadata.exposureTimeNs > 0) {
                    metadata.exposureTimeNs / NS_PER_SECOND.toDouble()
                } else {
                    0.0
                }

                exif.setAttribute(ExifInterface.TAG_MAKE, metadata.make)
                exif.setAttribute(ExifInterface.TAG_MODEL, metadata.model)
                exif.setAttribute(ExifInterface.TAG_SOFTWARE, CAMERA_APP_NAME)
                exif.setAttribute(ExifInterface.TAG_ARTIST, CAMERA_APP_NAME)
                exif.setAttribute(
                    ExifInterface.TAG_FOCAL_LENGTH,
                    "${(metadata.focalLength * 1000).toInt()}/1000"
                )
                exif.setAttribute(ExifInterface.TAG_F_NUMBER, metadata.aperture.toString())
                exif.setAttribute(ExifInterface.TAG_PHOTOGRAPHIC_SENSITIVITY, metadata.iso.toString())
                exif.setAttribute(ExifInterface.TAG_EXPOSURE_TIME, exposureTime.toString())

                Log.d(
                    LOG_TAG,
                    "Writing EXIF: ISO=${metadata.iso}, Exp=${exposureTime}s, Focal=${metadata.focalLength}, " +
                        "Aperture=${metadata.aperture}, Location=${metadata.location}"
                )

                metadata.location?.let { location ->
                    exif.setLatLong(location.latitude, location.longitude)
                    exif.setGpsInfo(location)
                }

                exif.saveAttributes()
            }
            val exifDoneMs = System.currentTimeMillis()

            contentValues.clear()
            contentValues.put(MediaStore.MediaColumns.IS_PENDING, 0)
            context.contentResolver.update(imageUri, contentValues, null, null)

            if (BuildConfig.DEBUG) {
                Log.d(
                    LOG_TAG,
                    "[PERF_STILL] total=${exifDoneMs - shutterStart}ms readback=${readbackTime}ms " +
                        "bitmap=${bitmapTime}ms encode=${encodeDoneMs - encodeStartMs}ms " +
                        "exif=${exifDoneMs - encodeDoneMs}ms"
                    )
            }
        } catch (e: Exception) {
            Log.e(LOG_TAG, "capture Failed to save image or metadata", e)
            context.mainExecutor.execute {
                Toast.makeText(context, "Failed to save image", Toast.LENGTH_SHORT).show()
            }
        }
    }
}

@Composable
fun BuildTimerText() {
    var buildTimeText by remember { mutableStateOf("Built: calculating...") }

    LaunchedEffect(Unit) {
        while (true) {
            val diffMin = (System.currentTimeMillis() - BuildConfig.BUILD_TIME) / MS_PER_MINUTE
            buildTimeText = if (diffMin < 1) "Built: just now" else "Built: $diffMin min ago"
            delay(BUILD_TIMER_TICK_MS)
        }
    }

    Surface(
